void Write8BIMProfile(Image *image, const char *name, const StringInfo *profile) {
    ssize_t id;
    StringInfo
        *string_info = NULL;
    unsigned char
        *p = NULL;
    size_t
        length = 0;

    id = Get8BIMProfileID(name);
    if (id < 0)
        return;

    string_info = GetImageProfile(image, "8BIM");
    if (string_info == (StringInfo *) NULL)
        return;

    p = GetStringInfoDatum(string_info);
    if (p == (unsigned char *) NULL)
        return;

    length = GetStringInfoLength(string_info);
    if (length < 12)
        return;

    p += 8;
    while ((size_t) (p - GetStringInfoDatum(string_info)) < length) {
        unsigned int
            signature = 0;

        signature = (unsigned int) ((p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3]);
        if (signature != 0x3842494D)
            break;

        {
            unsigned int
                resource_id = 0;

            resource_id = (unsigned int) ((p[4] << 24) | (p[5] << 16) | (p[6] << 8) | p[7]);
            if (resource_id != (unsigned int) id)
                continue;

            {
                unsigned int
                    count = 0,
                    offset = 0;

                count = (unsigned int) ((p[8] << 24) | (p[9] << 16) | (p[10] << 8) | p[11]);
                if (count == 0)
                    continue;

                offset = 12;
                for ( ; count > 0; count--) {
                    unsigned int
                        entry_length = 0;

                    entry_length = (unsigned int) ((p[offset + 8] << 24) |
                        (p[offset + 9] << 16) | (p[offset + 10] << 8) |
                        p[offset + 11]);
                    if (entry_length == 0)
                        continue;

                    if ((offset + 12 + entry_length) > length)
                        continue;

                    if (profile != (StringInfo *) NULL) {
                        StringInfo
                            *profile_info = NULL;

                        profile_info = CloneStringInfo((StringInfo *) NULL);
                        if (profile_info != (StringInfo *) NULL) {
                            SetStringInfoLength(profile_info, entry_length);
                            memcpy(GetStringInfoBody(profile_info), p + offset + 12, entry_length);
                            SetImageProfile(image, name, profile_info);
                            profile_info = DestroyStringInfo(profile_info);
                        }
                    }

                    offset += 12 + entry_length;
                }
            }
        }

        break;
    }

    string_info = DestroyStringInfo(string_info);
}

