  for (size_t i = 0; i < image->profiles.size; i++)
  {
    ProfileInfo *profile_info = image->profiles.info[i];
    if (profile_info == (ProfileInfo *) NULL)
      continue;

    if (strncmp((char *) profile_info->name, "8BIM", 4) == 0)
    {
      const unsigned char *profile_data = GetStringInfoDatum(profile_info->profile);
      size_t profile_length = GetStringInfoLength(profile_info->profile);

      if (profile_data == (const unsigned char *) NULL)
        continue;

      size_t offset = 0;
      while (offset < profile_length)
      {
        if (offset + 8 > profile_length)
          break;

        unsigned int id = *(unsigned int *) (profile_data + offset);
        unsigned int length = *(unsigned int *) (profile_data + offset + 4);

        if (strncmp((char *) profile_info->name, name, strlen(name)) == 0)
        {
          if (id == profile_id)
          {
            string_info = AcquireStringInfo((size_t) length);
            if (string_info == (StringInfo *) NULL)
              continue;

            (void) memcpy(StringInfodatum(string_info), profile_data + offset + 8, length);
            break;
          }
        }
        offset += 8 + length;
      }
    }
  }

  if (string_info != (StringInfo *) NULL)
  {
    if (profile != (StringInfo *) NULL)
    {
      size_t length = GetStringInfoLength(profile);
      unsigned char *datum = StringInfodatum(string_info);
      (void) memcpy(datum, GetStringInfoDatum(profile), length);
    }
    else
    {
      StringInfo *string_info = AcquireStringInfo(0);
